pub struct Sandbox<'a> { audio: &'a mut Audio, fx: &'a mut Particles }   // the primitives
impl Sandbox<'_> {
    pub fn play_sound(&mut self, id: SoundId, volume: f32) { self.audio.play(id, volume) }
    pub fn spawn_particles(&mut self, kind: ParticleType, n: u32) { self.fx.spawn(kind, n) }
}

pub trait Power { fn activate(&mut self, sb: &mut Sandbox<'_>); }        // the sandbox method

struct SkyLaunch;
impl Power for SkyLaunch {
    fn activate(&mut self, sb: &mut Sandbox<'_>) {                      // composes primitives only
        sb.play_sound(SoundId::Sproing, 1.0);
        sb.spawn_particles(ParticleType::Dust, 10);
    }
}
